#include <stdio.h>

int solution(int floors[], int floors_len) {
    int best = 1;
    int up = 1, down = 1;
    for (int i = 1; i < floors_len; i++) {
        if (floors[i] > floors[i - 1]) {
            up++;
            down = 1;
        } else if (floors[i] <= floors[i - 1]) {
            down++;
            up = 1;
        } else {
            up = 1;
            down = 1;
        }
        if (up > best) best = up;
        if (down > best) best = down;
    }
    return best;
}

