#include <stdio.h>

void count_up(int land[], int land_len, int up[]) {
    up[0] = 1;
    for (int i = 1; i < land_len; i++) {
        if (land[i] > land[i - 1]) up[i] = up[i - 1] + 1;
        else up[i] = 1;
    }
}

void count_down(int land[], int land_len, int down[]) {
    down[land_len - 1] = 1;
    for (int i = land_len - 2; i >= 0; i--) {
        if (land[i + 1] > land[i]) down[i] = down[i + 1] + 1;
        else down[i] = 1;
    }
}

int solution(int land[], int land_len) {
    int up[100], down[100];
    count_up(land, land_len, up);
    count_down(land, land_len, down);
    int best = 0;
    for (int i = 0; i < land_len; i++) {
        if (up[i] > 1 && down[i] > 1) {
            int len = up[i] + down[i] - 1;
            if (len > best) best = len;
        }
    }
    return best;
}

